using Namaa.Application.Common.Concurrency;using Namaa.Domain.Entities;namespace Namaa.Application.Invoices.Dtos;public sealed record InvoiceItemDto(long Id,long InvoiceId,short LineNumber,string Description,decimal Quantity,decimal UnitPrice,decimal DiscountAmount,decimal TaxAmount,decimal LineTotal,long? ServiceId,string ParentRowVersion){internal static InvoiceItemDto FromEntity(InvoiceItem e)=>new(e.Id,e.InvoiceId,e.LineNumber,e.Description,e.Quantity,e.UnitPrice,e.DiscountAmount,e.TaxAmount,e.LineTotal,e.ServiceId,ConcurrencyToken.Encode(e.Invoice.RowVersion));}public sealed record InvoiceDto(long Id,long? ProjectId,string InvoiceNumber,Namaa.Domain.Enums.InvoiceStatus Status,DateTime IssueDate,DateTime? DueDate,decimal SubTotal,decimal DiscountAmount,decimal TaxAmount,decimal TotalAmount,string? Notes,long CreatedByUserId,long? CustomerId,DateTime CreatedAt,DateTime? UpdatedAt,string RowVersion,IReadOnlyList<InvoiceItemDto> Items){internal static InvoiceDto FromEntity(Invoice e)=>new(e.Id,e.ProjectId,e.InvoiceNumber,e.Status,e.IssueDate,e.DueDate,e.SubTotal,e.DiscountAmount,e.TaxAmount,e.TotalAmount,e.Notes,e.CreatedByUserId,e.CustomerId,e.CreatedAt,e.UpdatedAt,ConcurrencyToken.Encode(e.RowVersion),e.Items.Select(InvoiceItemDto.FromEntity).ToList());}
